import java.util.*;

class Solution {
    private int[] parent;

    public List<List<String>> mergeCards(String[][] cards) {
        Map<String, Integer> id = new HashMap<>();
        Map<String, String> owner = new HashMap<>();
        for (String[] card : cards)
            for (int i = 1; i < card.length; i++)
                if (!id.containsKey(card[i])) { id.put(card[i], id.size()); owner.put(card[i], card[0]); }
        parent = new int[id.size()];
        for (int i = 0; i < parent.length; i++) parent[i] = i;
        for (String[] card : cards) {
            int first = find(id.get(card[1]));
            for (int i = 2; i < card.length; i++) {
                int r = find(id.get(card[i]));
                if (r != first) parent[r] = first; // same card = same person
            }
        }
        Map<Integer, List<String>> groups = new HashMap<>();
        for (String email : id.keySet())
            groups.computeIfAbsent(find(id.get(email)), k -> new ArrayList<String>()).add(email);
        List<List<String>> res = new ArrayList<>();
        for (List<String> emails : groups.values()) {
            Collections.sort(emails);
            List<String> person = new ArrayList<>();
            person.add(owner.get(emails.get(0)));
            person.addAll(emails);
            res.add(person);
        }
        return res;
    }

    private int find(int x) {
        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
}

