class Solution:
    def mergeCards(self, cards: List[List[str]]) -> List[List[str]]:
        p = {}; owner = {}
        def f(x):
            while p[x] != x: p[x] = p[p[x]]; x = p[x]
            return x
        for card in cards:
            for e in card[1:]:
                p.setdefault(e, e); owner[e] = card[0]
                p[f(e)] = f(card[1])
        groups = defaultdict(list)
        for e in p: groups[f(e)].append(e)
        return [[owner[r]] + sorted(es) for r, es in groups.items()]

