function mergeCards(cards) {
  const adj = new Map(), owner = new Map();
  const add = (a, b) => { if (!adj.has(a)) adj.set(a, []); adj.get(a).push(b); };
  for (const c of cards) for (let i = 1; i < c.length; i++) { owner.set(c[i], c[0]); add(c[i], c[1]); add(c[1], c[i]); }
  const seen = new Set(), out = [];
  for (const e of adj.keys()) {
    if (seen.has(e)) continue; seen.add(e); const st = [e], comp = [];
    while (st.length) { const v = st.pop(); comp.push(v); for (const u of adj.get(v)) if (!seen.has(u)) { seen.add(u); st.push(u); } }
    comp.sort((a, b) => a < b ? -1 : a > b ? 1 : 0); out.push([owner.get(e), ...comp]);
  }
  return out;
}
